"use server";

import { redirect } from "next/navigation";
import { appUrl, getStripe } from "@/lib/stripe";
import { getCurrentUser } from "@/lib/users";

export async function startCheckout() {
  const user = await getCurrentUser();
  if (!user) redirect("/");
  if (user.plan === "pro") redirect("/dashboard");

  const priceId = process.env.STRIPE_PRO_PRICE_ID;
  if (!priceId) throw new Error("STRIPE_PRO_PRICE_ID is not set");

  const session = await getStripe().checkout.sessions.create({
    mode: "subscription",
    line_items: [{ price: priceId, quantity: 1 }],
    client_reference_id: user.id,
    // Reuse the Stripe customer if we have one, otherwise let Checkout create it.
    ...(user.stripeCustomerId
      ? { customer: user.stripeCustomerId }
      : { customer_email: user.email }),
    subscription_data: { metadata: { userId: user.id } },
    success_url: `${appUrl()}/dashboard?checkout=success`,
    cancel_url: `${appUrl()}/dashboard?checkout=canceled`,
  });

  if (!session.url) throw new Error("Stripe did not return a checkout URL");
  redirect(session.url);
}
EOF
