import type Stripe from "stripe";
import { getStripe } from "@/lib/stripe";
import { getUserByStripeCustomerId, updateUserBilling } from "@/lib/users";

export const runtime = "nodejs";

const ACTIVE = new Set(["active", "trialing"]);

function customerId(c: string | Stripe.Customer | Stripe.DeletedCustomer | null) {
  return typeof c === "string" ? c : c?.id;
}

export async function POST(request: Request) {
  const secret = process.env.STRIPE_WEBHOOK_SECRET;
  const signature = request.headers.get("stripe-signature");
  if (!secret || !signature) {
    return new Response("Webhook not configured", { status: 400 });
  }

  // Signature verification needs the raw, unparsed body.
  const body = await request.text();
  let event: Stripe.Event;
  try {
    event = getStripe().webhooks.constructEvent(body, signature, secret);
  } catch {
    return new Response("Invalid signature", { status: 400 });
  }

  switch (event.type) {
    case "checkout.session.completed":
    case "checkout.session.async_payment_succeeded": {
      const session = event.data.object;
      if (session.mode !== "subscription" || session.payment_status !== "paid") break;
      const userId = session.client_reference_id;
      if (!userId) break;
      await updateUserBilling(userId, {
        plan: "pro",
        stripeCustomerId: customerId(session.customer),
        stripeSubscriptionId:
          typeof session.subscription === "string"
            ? session.subscription
            : session.subscription?.id,
      });
      break;
    }
    case "customer.subscription.updated":
    case "customer.subscription.deleted": {
      const sub = event.data.object;
      const cid = customerId(sub.customer);
      const user = cid ? await getUserByStripeCustomerId(cid) : undefined;
      // Ignore events for a subscription other than the one we track.
      if (!user || user.stripeSubscriptionId !== sub.id) break;
      await updateUserBilling(user.id, {
        plan: ACTIVE.has(sub.status) ? "pro" : "free",
      });
      break;
    }
  }

  return Response.json({ received: true });
}
EOF
